"""Each README command-table cell must equal the command's help string exactly."""
import pathlib
import re
import unittest

from textkit.cli import COMMANDS

ROOT = pathlib.Path(__file__).resolve().parent.parent


def readme_cells():
    readme = (ROOT / "README.md").read_text()
    rows = re.findall(r"^\| `([^`]+)` \| (.*?) \|$", readme, flags=re.M)
    return dict(rows)


class DocSyncTest(unittest.TestCase):
    def test_cells_match_help(self):
        cells = readme_cells()
        for name, c in COMMANDS.items():
            with self.subTest(command=name):
                self.assertIn(name, cells)
                self.assertEqual(cells[name], c["help"])
import contextlib
import io
import unittest

from textkit.cli import main


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class CliTest(unittest.TestCase):
    def test_shout(self):
        self.assertEqual(run("shout", "hey"), (0, "HEY\n", ""))

    def test_commands_lists_itself(self):
        code, out, _ = run("commands")

